;
; The overlay loader, for the HDOS build (H89_HDOS).
;
; HDOS leaves the program's own file open on channel -1, so the overlays are
; appended to BARRAGE.ABS past the part HDOS loads -- each from a sector
; boundary, in the order of src/h89/mmap.inc -- and read from there into the
; window at H89_OVL_WIN with .POSIT and .READ. That works from any disk HDOS
; can RUN from, SY1: or FN0:, without knowing which.
;
; The entry points of an overlay are stubs in resident code (generated by
; tools/h89/mkovl.py): `call ovl_tramp; defq target`, the target's 64K digit
; its overlay. ovl_tramp loads that overlay if the window holds another, takes
; the caller's return address off the stack so the target sees its arguments
; where a direct call leaves them, calls it, and on the way back loads the
; overlay of the caller (if it was an overlay and something displaced it; a
; resident caller asks for nothing) and returns to it.
;
; A load is disk I/O, and from FN0: it is the FujiNet card's, so before one
; the link's request in flight is let finish (_ovl_quiesce, nstrans.c).
;

IFDEF H89_HDOS

    EXTERN  __BSS_head
    EXTERN  __OVL_ROOM_head, __OVL_ROOM_END_head
    EXTERN  __OVL_FIELD_head, __OVL_FIELD_END_head
    EXTERN  __restore_sp_onexit
    EXTERN  _plat_shutdown
    EXTERN  _ovl_quiesce
    EXTERN  _ticks_now

    PUBLIC  ovl_tramp
    PUBLIC  _ovl_tab
    PUBLIC  _ovl_loads
    PUBLIC  _ovl_ticks

    defc    POSIT = 0x27
    defc    READ = 0x04
    defc    SCOUT = 0x02
    defc    SELF = 0xFF             ; the channel HDOS loaded the program on

    ; Each overlay's first sector in the file and its length in sectors. The
    ; file is the 8-byte ABS header and the image up to BSS, padded to a
    ; sector, then the overlays, each padded to one. tools/h89/hdosovl.py
    ; packs it so and checks this table against what it packed.
    defc    IMG = (__BSS_head - H89_ORG + 8 + 255) / 256
    defc    N_ROOM = (__OVL_ROOM_END_head - __OVL_ROOM_head + 255) / 256
    defc    N_FIELD = (__OVL_FIELD_END_head - __OVL_FIELD_head + 255) / 256

    SECTION rodata_user
_ovl_tab:
    defw    IMG
    defb    N_ROOM
    defw    IMG + N_ROOM
    defb    N_FIELD

    SECTION code_user

ovl_tramp:
    pop     hl                  ; -> the defq
    ld      e,(hl)
    inc     hl
    ld      d,(hl)
    inc     hl
    ld      c,(hl)              ; the overlay
    pop     hl                  ; the caller's return address
    push    de                  ; the target
    push    hl
    ld      hl,(ovl_sp)         ; a frame: that, and the overlay the caller wanted
    dec     hl
    ld      a,(ovl_req)
    ld      (hl),a
    pop     de
    dec     hl
    ld      (hl),d
    dec     hl
    ld      (hl),e
    ld      (ovl_sp),hl
    ld      a,c
    ld      (ovl_req),a
    call    ovl_need
    pop     hl
    call    jphl                ; the target sees its arguments where it would
    push    hl                  ; the result, which may be a long
    push    de
    ld      hl,(ovl_sp)
    ld      e,(hl)
    inc     hl
    ld      d,(hl)
    inc     hl
    ld      a,(hl)
    inc     hl
    ld      (ovl_sp),hl
    ld      (ovl_req),a
    push    de
    call    ovl_need
    pop     bc
    pop     de
    pop     hl
    push    bc
    ret
jphl:
    jp      (hl)

; The window to hold overlay A (0: whatever is there will do).
ovl_need:
    or      a
    ret     z
    ld      hl,ovl_cur
    cp      (hl)
    ret     z
    ld      (hl),0              ; neither the old one nor the new, until read
    ld      (ovl_n),a
    push    ix
    push    iy
    call    _ticks_now          ; (what a load costs: 2 ms ticks, a rig reads _ovl_ticks)
    ld      (ovl_t0),hl
    call    _ovl_quiesce        ; (the link's request in flight finishes first)
    ld      hl,(_ovl_loads)
    inc     hl
    ld      (_ovl_loads),hl
    ld      a,(ovl_n)
    dec     a
    ld      e,a
    add     a,a
    add     a,e
    ld      e,a
    ld      d,0
    ld      hl,_ovl_tab
    add     hl,de
    ld      c,(hl)
    inc     hl
    ld      b,(hl)
    inc     hl
    ld      a,(hl)
    push    af
    ld      a,SELF
    rst     0x38
    defb    POSIT
    pop     de                  ; D = sectors
    jr      c,ovl_fail
    ld      b,d
    ld      c,0
    ld      de,H89_OVL_WIN
    ld      a,SELF
    rst     0x38
    defb    READ
    jr      c,ovl_fail
    call    _ticks_now
    ld      de,(ovl_t0)
    or      a
    sbc     hl,de
    ld      de,(_ovl_ticks)
    add     hl,de
    ld      (_ovl_ticks),hl
    pop     iy
    pop     ix
    ld      a,(ovl_n)
    ld      (ovl_cur),a
    ret

; Nothing can go on without the code, so say which and leave.
ovl_fail:
    push    af
    call    _plat_shutdown
    ld      hl,ovl_msg1
    call    ovl_puts
    ld      a,(ovl_n)
    call    ovl_dec
    ld      hl,ovl_msg2
    call    ovl_puts
    pop     af
    call    ovl_dec
    ld      a,10
    rst     0x38
    defb    SCOUT
    jp      __restore_sp_onexit

ovl_puts:
    ld      a,(hl)
    or      a
    ret     z
    push    hl
    rst     0x38
    defb    SCOUT
    pop     hl
    inc     hl
    jr      ovl_puts

; A, 0-99, in decimal.
ovl_dec:
    ld      b,'0' - 1
ovl_tens:
    inc     b
    sub     10
    jr      nc,ovl_tens
    add     a,'0' + 10
    push    af
    ld      a,b
    rst     0x38
    defb    SCOUT
    pop     af
    rst     0x38
    defb    SCOUT
    ret

    SECTION rodata_user
ovl_msg1:
    defm    "OVL ", 0
ovl_msg2:
    defm    " ERR ", 0

    SECTION data_user
ovl_sp:
    defw    ovl_stk_end

    SECTION bss_user
_ovl_loads:
    defw    0                   ; loads so far (a rig reads it)
_ovl_ticks:
    defw    0                   ; the 2 ms ticks they took
ovl_t0:
    defw    0
ovl_cur:
    defb    0                   ; the overlay in the window
ovl_req:
    defb    0                   ; the overlay the innermost call wants
ovl_n:
    defb    0
ovl_stk:
    defs    3 * 8               ; calls through the stubs nest two deep here
ovl_stk_end:

ENDIF
